pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    // Keep the delay bounded before and after each doubling, so large retry
    // budgets cannot overflow the arithmetic.
    let mut delay = config.base_delay_ms.min(config.max_delay_ms);
    let attempts = config.max_attempts.max(1);

    for attempt in 0..attempts {
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() => return Err(error),
            Err(error) if attempt + 1 == attempts => return Err(error),
            Err(_) => {
                sleeper.sleep_ms(delay);
                delay = delay.saturating_mul(2).min(config.max_delay_ms);
            }
        }
    }

    unreachable!("retry loop always returns from an attempt")
}

